values ('hsk1-l14', 'hsk1', 'HSK1', 14, '她买了不少衣服', 'Tā mǎile bù shǎo yīfu', 'She has bought quite a few clothes', '{"level": "hsk1", "lesson": 14, "book": "HSK1", "title_zh": "她买了不少衣服", "title_pinyin": "Tā mǎile bù shǎo yīfu", "title_en": "She has bought quite a few clothes", "textbook": {"ref": {"book": "textbook", "pages": [124, 125, 126, 127, 128, 129, 130, 131]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words/phrases.", "items": ["①苹果 píngguǒ", "②车 chē", "③衣服 yīfu", "④商店 shāngdiàn", "⑤书店 shūdiàn", "⑥英语书 Yīngyǔ shū"], "pictures_desc_en": ["A: rows of parked cars", "B: colourful clothes hanging on a rack", "C: a red hardcover book lying on top of another book on a wooden table", "D: red apples, one of them cut in half", "E: a bookstore with tables and shelves of books and shoppers", "F: the interior atrium of a multi-storey shopping mall"]}], "pronunciation": [{"title_zh": "三音节词语的声调搭配（3）：三声音节开头", "rows": ["3+1+1 xǐyījī washing machine　3+1+2 pǔtōng rén common people　3+1+3 zǒngjīnglǐ general manager　3+1+4 huǒchē piào train ticket", "3+2+1 shǐxuéjiā historian　3+2+2 jǐngchájú police station　3+2+3 měinánzǐ handsome man　3+2+4 měiróngyuàn beauty salon", "3+3+1 biǎoyǎnjiā performer　3+3+2 xiǎo yǎnyuán little actor　3+3+3 Mǐlǎoshǔ Mickey Mouse　3+3+4 yǎnchànghuì concert", "3+4+1 dǎzìjī tapewriter　3+4+2 pǎobù xié running shoes　3+4+3 měishùguǎn art gallery　3+4+4 dǎ diànhuà to make a phone call"], "notes_zh": ["［4×4 声调搭配表，录音 14-4］"], "notes_en": ["Tone Collocation in Trisyllabic Words (3): words starting with a third-tone syllable"]}], "texts": [{"n": 1, "title_zh": "在宿舍", "title_en": "In the dorm", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "昨天上午你去哪儿了？", "pinyin": "Zuótiān shàngwǔ nǐ qù nǎr le?"}, {"speaker": "B", "zh": "我去商店买东西了。", "pinyin": "Wǒ qù shāngdiàn mǎi dōngxi le."}, {"speaker": "A", "zh": "你买什么了？", "pinyin": "Nǐ mǎi shénme le?"}, {"speaker": "B", "zh": "我买了一点儿苹果。", "pinyin": "Wǒ mǎile yìdiǎnr píngguǒ."}], "english_version": "A: Where did you go yesterday morning?\nB: I went shopping.\nA: What did you buy?\nB: I bought some apples.", "new_words": [{"n": 1, "zh": "东西", "pinyin": "dōngxi", "pos": "n.", "en": "thing, stuff", "text": 1}, {"n": 2, "zh": "一点儿", "pinyin": "yìdiǎnr", "pos": "num.-m.", "en": "a few, a little", "text": 1}, {"n": 3, "zh": "苹果", "pinyin": "píngguǒ", "pos": "n.", "en": "apple", "text": 1}]}, {"n": 2, "title_zh": "在公司", "title_en": "In the company", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你看见张先生了吗？", "pinyin": "Nǐ kànjiàn Zhāng xiānsheng le ma?"}, {"speaker": "B", "zh": "看见了，他去学开车了。", "pinyin": "Kànjiàn le, tā qù xué kāi chē le."}, {"speaker": "A", "zh": "他什么时候能回来？", "pinyin": "Tā shénme shíhou néng huílai?"}, {"speaker": "B", "zh": "40分钟后回来。", "pinyin": "Sìshí fēnzhōng hòu huílai."}], "english_version": "A: Have you seen Mr. Zhang?\nB: Yes. He has gone to a driving lesson.\nA: When can he come back?\nB: After 40 minutes.", "new_words": [{"n": 4, "zh": "看见", "pinyin": "kànjiàn", "pos": "v.", "en": "to see", "text": 2}, {"n": 5, "zh": "先生", "pinyin": "xiānsheng", "pos": "n.", "en": "Mr., sir", "text": 2}, {"n": 6, "zh": "开", "pinyin": "kāi", "pos": "v.", "en": "to drive", "text": 2}, {"n": 7, "zh": "车", "pinyin": "chē", "pos": "n.", "en": "car, vehicle", "text": 2}, {"n": 8, "zh": "回来", "pinyin": "huílai", "pos": "v.", "en": "to come back", "text": 2}, {"n": 9, "zh": "分钟", "pinyin": "fēnzhōng", "pos": "n.", "en": "minute", "text": 2}, {"n": 10, "zh": "后", "pinyin": "hòu", "pos": "n.", "en": "after, afterwards, later", "text": 2}], "proper_nouns": [{"zh": "张", "pinyin": "Zhāng", "en": "Zhang, a Chinese family name"}]}, {"n": 3, "title_zh": "在商店门口", "title_en": "Outside a store", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "王方的衣服太漂亮了！", "pinyin": "Wáng Fāng de yīfu tài piàoliang le."}, {"speaker": "B", "zh": "是啊，她买了不少衣服。", "pinyin": "Shì a, tā mǎile bùshǎo yīfu."}, {"speaker": "A", "zh": "你买什么了？", "pinyin": "Nǐ mǎi shénme le?"}, {"speaker": "B", "zh": "我没买，这些都是王方的东西。", "pinyin": "Wǒ méi mǎi, zhèxiē dōu shì Wáng Fāng de dōngxi."}], "english_version": "A: Wang Fang’s dress is so pretty!\nB: Yes. She has bought quite a few clothes.\nA: What did you buy?\nB: I bought nothing. All these are Wang Fang’s stuff.", "new_words": [{"n": 11, "zh": "衣服", "pinyin": "yīfu", "pos": "n.", "en": "clothes", "text": 3}, {"n": 12, "zh": "漂亮", "pinyin": "piàoliang", "pos": "adj.", "en": "beautiful, pretty", "text": 3}, {"n": 13, "zh": "啊", "pinyin": "a", "pos": "part.", "en": "a modal particle used at the end of a sentence as a sign of confirmation or defense", "star": true, "text": 3}, {"n": 14, "zh": "少", "pinyin": "shǎo", "pos": "adj.", "en": "little, few", "text": 3}, {"n": 14, "zh": "不少", "pinyin": "bùshǎo", "pos": "adj.", "en": "quite a few, many", "text": 3}, {"n": 15, "zh": "这些", "pinyin": "zhèxiē", "pos": "pron.", "en": "these", "text": 3}, {"n": 16, "zh": "都", "pinyin": "dōu", "pos": "adv.", "en": "both, all", "text": 3}]}], "grammar": [{"n": 1, "title_zh": "“了”表发生或完成", "title_en": "“了” Indicating Occurrence or Completion", "explanation_zh": "“了”用于句尾。例如：\n“了”用于动词后带宾语。动词后的宾语前面一般要有定语，如数量词或形容词、代词等。例如：\n上述两种用法的“了”的否定形式是：［没＋动词（＋宾语）］，“了”要去掉。例如：", "explanation_en": "“了” can be used at the end of a sentence. For example:\n“了” can also be used between a verb and its object. There is usually a modifier before the object of the verb, such as a numeral classifier, an adjective or a pronoun, etc. For example:\nThe negative form of “了” in both cases above is “没 + verb + (object)”. In the negative form, “了” should be omitted. For example:", "structure_rows": ["表1: Subject | Predicate | 了", "我 | 去商店 | 了。", "他 | 去学开车 | 了。", "你 | 买什么 | 了？", "表2: Subject | Predicate: Verb | 了 | Number-Measure Word/Adjective/Pronoun | Object", "她 | 买 | 了 | 一点儿 | 苹果。", "我 | 买 | 了 | 不少 | 衣服。", "你 | 看见 | 了 | 几个 | 人？", "表3: Subject | 没 | Predicate", "她 | 没 | 去商店。", "我 | 没 | 买。", "我 | 没 | 看见张先生。"], "examples": [{"n": 1, "zh": "我去商店了。", "note_zh": "表1"}, {"n": 2, "zh": "他去学开车了。", "note_zh": "表1"}, {"n": 3, "zh": "你买什么了？", "note_zh": "表1"}, {"n": 4, "zh": "她买了一点儿苹果。", "note_zh": "表2"}, {"n": 5, "zh": "我买了不少衣服。", "note_zh": "表2"}, {"n": 6, "zh": "你看见了几个人？", "note_zh": "表2"}, {"n": 7, "zh": "她没去商店。", "note_zh": "表3"}, {"n": 8, "zh": "我没买。", "note_zh": "表3"}, {"n": 9, "zh": "我没看见张先生。", "note_zh": "表3"}]}, {"n": 2, "title_zh": "名词“后”", "title_en": "The Noun “后”", "explanation_zh": "名词“后”表示现在或者所说的某个时间以后的时间。例如：", "explanation_en": "The noun “后” indicates a period after the present time or the time being mentioned. For example:", "examples": [{"n": 1, "zh": "五点后　40分钟后　星期三后"}, {"n": 2, "zh": "A：你几点去工作？　B：八点后。"}, {"n": 3, "zh": "A：你什么时候回家？　B：五点后。"}, {"n": 4, "zh": "A：他什么时候能回来？　B：40分钟后回来。"}]}, {"n": 3, "title_zh": "语气助词“啊”", "title_en": "The Modal Particle “啊”", "explanation_zh": "语气词“啊”用在陈述句末，使句子带上一层感情色彩。“啊”常受到前一字尾音的影响而发生不同的变音，书面上有时按变音写成不同的字。", "explanation_en": "The modal particle “啊” is used at the end of a declarative sentence to set the mood. The pronunciation of “啊” varies with the finals of the syllables before it, and in written Chinese, the variants are represented by different characters sometimes.", "structure_rows": ["The Final of the Syllable before It | The Pronunciation of “啊”", "a　e　i　o　ü | a → ia", "u　ao　ou | a → ua", "-n | a → na", "-ng | a → nga", "-i（zi，ci，si 中） | a → za", "-i（zhi，chi，shi，ri 中） | a → ra"], "examples": [{"n": 1, "zh": "A：你是王小姐吗？　B：是啊。"}, {"n": 2, "zh": "A：你想去吃中国菜吗？　B：好啊。"}, {"n": 3, "zh": "A：王方的衣服太漂亮了！　B：是啊，她买了不少衣服。"}]}, {"n": 4, "title_zh": "副词“都”", "title_en": "The Adverb “都”", "explanation_zh": "“都”表示总括全部，所总括的对象必须放在“都”的前面。例如：", "explanation_en": "“都” means “both/all”. The people or objects included are put before “都”. For example:", "examples": [{"n": 1, "zh": "我们都是中国人。"}, {"n": 2, "zh": "他们都喜欢喝茶。"}, {"n": 3, "zh": "这些都是王方的东西。"}]}], "exercises": [{"n": 1, "type_zh": "分角色朗读课文", "instruction_zh": "分角色朗读课文", "instruction_en": "Role-play the dialogues.", "items": []}, {"n": 2, "type_zh": "回答问题", "instruction_zh": "根据课文内容回答问题", "instruction_en": "Answer the questions based on the dialogues.", "items": [{"n": 1, "zh": "昨天上午她去哪儿了？", "pinyin": "Zuótiān shàngwǔ tā qù nǎr le?"}, {"n": 2, "zh": "她买什么了？", "pinyin": "Tā mǎi shénme le?"}, {"n": 3, "zh": "张先生什么时候能回来？", "pinyin": "Zhāng xiānsheng shénme shíhou néng huílai?"}, {"n": 4, "zh": "王方买什么了？", "pinyin": "Wáng Fāng mǎi shénme le?"}, {"n": 5, "zh": "王方的朋友买什么了？", "pinyin": "Wáng Fāng de péngyou mǎi shénme le?"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "妈妈去商店买了________。", "pinyin": "Māma qù shāngdiàn mǎile", "picture_desc_en": "a woman and a small child choosing fruit at a market stall piled with fruit"}, {"n": 2, "zh": "她下午去学________了。", "pinyin": "Tā xiàwǔ qù xué le.", "picture_desc_en": "a smiling young woman at the steering wheel of a car, an older man in the passenger seat beside her"}, {"n": 3, "zh": "桌子上________是张先生的东西。", "pinyin": "Zhuōzi shang shì Zhāng xiānsheng de dōngxi.", "picture_desc_en": "a cup of coffee, a stack of books and a pair of glasses on a table"}, {"n": 4, "zh": "丽丽买了________衣服。", "pinyin": "Lìli mǎile yīfu.", "picture_desc_en": "a smiling young woman in a clothes shop holding up a green dress, shopping bags at her feet"}]}], "characters": {"knowledge_title_zh": "认识独体字／汉字偏旁“月”和“扌”", "knowledge_zh": "1 认识独体字\n（1）“开”，字形像一双手抽拉门栓。本义是抽掉门栓，启动关闭的门，现在意思很多，如“开车”、“开花”。［字形演变图3步 → 开 kāi；田字格笔顺4步］\n（2）“车”，字形像某种器械两边各有一个轮子，本义是有轮子、靠牛马拉动的战斗工具，现在泛指陆上运输、交通工具，如“出租车”、“火车”。［字形演变图4步 → 车 chē；田字格笔顺4步］\n（3）“回”，字形像水流回旋的样子，本义是“旋转”，后来表示“还、回来”。［字形演变图4步 → 回 huí；田字格笔顺6步］\n2 汉字偏旁“月”和“扌”\n偏旁 | 解释 | 例字\n月 | 肉月旁，一般和人体、肉有关系。 | 服 fú、胖 pàng\n扌 | 提手旁，一般表示和手有关的动作。 | 打 dǎ、找 zhǎo", "knowledge_en": "Single-Component Characters: (1) Shaped like two hands pulling a door latch, the original meaning of “开” was to pull out the door latch and open the door. Now it has many meanings, such as “开车 (to drive a car)” and “开花 (to bloom)”. (2) “车”, originally shaped like an equipment with a wheel on both sides, referred to a wheeled vehicle used in wars, pulled by an ox or a horse. Now it refers to all the vehicles on land for transportation, such as “出租车 (taxi)” and “火车 (train)”. (3) “回” is shaped like a whirling flow of water. It originally meant “to rotate”, and now it means “to return”.\nChinese Radicals: “月” and “扌” — The radical “月” is usually related to human body or flesh: 服 fú clothes; 胖 pàng fat. The radical “扌” usually indicates an action related to a hand: 打 dǎ to beat, to hit; 找 zhǎo to look for.", "characters": [{"zh": "开", "pinyin": "kāi", "note_zh": "独体字：字形像一双手抽拉门栓，本义是抽掉门栓，启动关闭的门（字形演变图3步 + 笔顺4步图：一 → 二 → … → 开）"}, {"zh": "车", "pinyin": "chē", "note_zh": "独体字：字形像某种器械两边各有一个轮子，本义是有轮子、靠牛马拉动的战斗工具（字形演变图4步 + 笔顺4步图：一 → … → 车）"}, {"zh": "回", "pinyin": "huí", "note_zh": "独体字：字形像水流回旋的样子，本义是“旋转”，后来表示“还、回来”（字形演变图4步 + 笔顺6步图：丨 → 冂 → … → 回）"}, {"zh": "服", "pinyin": "fú", "note_zh": "偏旁“月”例字（clothes）"}, {"zh": "胖", "pinyin": "pàng", "note_zh": "偏旁“月”例字（fat）"}, {"zh": "打", "pinyin": "dǎ", "note_zh": "偏旁“扌”例字（to beat, to hit）"}, {"zh": "找", "pinyin": "zhǎo", "note_zh": "偏旁“扌”例字（to look for）"}]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，询问对方购买的物品。", "instruction_en": "Work in pairs and ask about the things your partner has bought.", "example_zh": ["例如：", "A：你去商店买什么了？ Nǐ qù shāngdiàn mǎi shénme le?", "B：我买了…… Wǒ mǎile……", "词语框：苹果 píngguǒ　衣服 yīfu　杯子 bēizi　桌子 zhuōzi　书 shū"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，互相询问并记录小组成员一天的活动，每组请一位同学报告情况。", "instruction_en": "Work in groups of 3-4. Ask about what each of your group member did during a day in the past and take notes. Each group chooses one member to make a report.", "example_zh": ["例如：", "A：星期一上午你做什么了？ Xīngqī yī shàngwǔ nǐ zuò shénme le?", "B：我去电影院了。 Wǒ qù diànyǐngyuàn le.", "A：你看什么了？ Nǐ kàn shénme le?", "B：我看了一个中国电影。 Wǒ kànle yí ge Zhōngguó diànyǐng.", "表格：人名 Name | 时间 Time | 地方 Place | 做什么 Activity", "1 | 小王 Xiǎo Wáng | 星期一上午 xīngqī yī shàngwǔ | 电影院 diànyǐngyuàn | 看了一个电影 kànle yí ge diànyǐng", "（另有3行空白）"]}]}, "teacher": {"ref": {"book": "teacher", "pages": [92, 93, 94, 95, 96, 97, 98, 130, 131]}, "objectives_zh": ["重点词语：学生能够熟练掌握“东西、一点儿、开、回来、漂亮、少、这些”的词义和用法", "语言点：学生能够了解并掌握：（1）“了”表示发生或完成（2）名词“后”：表示现在或者所说的某个时间以后的时间（3）语气助词“啊”（4）副词“都”", "语音：学生熟悉三声音节开头的三音节词语的声调模式，并能正确朗读", "汉字：学生能够：（1）熟练认读本课生词（2）独立书写独体字：开、车、回（3）了解“月（肉月旁）、扌（提手旁）”所表示的意思", "功能：学生能够熟练：（1）询问和回答已经完成或发生的事件（2）描述现在或者所说的某个时间以后的时间（3）表达感叹的语气（4）表达全部、总括的意义"], "steps": [{"title_zh": "一 复习旧课", "body_zh": "1. 教师出示第13课生词卡片，要求学生快速认读下列生词。\n喂、也、学习（学）、上午、睡觉、电视、喜欢、给、打电话、吧、大卫\n2. 教师根据第13课重点内容简单提问，活跃课堂气氛。\n（1）你喜欢看电视吗？你喜欢看电影吗？\n（2）昨天晚上8点你在做什么呢？\n（3）今天早上7点你在做什么呢？\n（4）你常常给谁打电话？\n（5）你的电话号码是多少？"}, {"title_zh": "二 学习新课 1 热身", "body_zh": "教师可依次指示热身部分的图片，要求学生集体或单个说出图片对应的词语，教师评判正误，并注意纠正学生的发音错误。最后全体学生再次齐读热身环节的所有词语，要求语音标准、声调准确。\n答案：①D　②A　③B　④F　⑤E　⑥C"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n东西、一点儿、苹果、看见、先生、开、车、回来、分钟、后、衣服、漂亮、啊、少、这些、都、张\n• 教师使用生词卡片有拼音和汉字的一面，带领学生快速认读一遍本课生词；\n• 使用生词卡片只有汉字的一面，带领学生再次认读本课生词；\n• 请单个学生独自认读2–3个生词；\n• 最后全体学生再快速认读一遍本课所有生词。\n（2）重点生词扩展及常用搭配\n东西—什么东西—这是什么东西？\n　—我的东西—他的东西—老师的东西—谁的东西\n　—买东西—买什么东西—你想买什么东西？\n一点儿—一点儿东西—一点儿苹果—一点儿茶　［一点儿＋名词］\n　—买一点儿东西—吃一点儿苹果—喝一点儿茶\n开—开车—会开车—不会开车—学开车\n　—开车去学校—开车去商店—开车回家\n回来—能回来—什么时候能回来—你什么时候能回来？\n漂亮—很漂亮—太漂亮了\n　—漂亮的衣服—漂亮的杯子—漂亮的小猫\n少—很少—不少　［不少＋名词］\n　—不少衣服—不少苹果—不少学生\n这些—这些衣服—这些苹果—这些学生\n　↔那些↔哪些\n练习册相关练习：第99页／一／第一部分，第102页／二／第一部分"}, {"title_zh": "3 语言点（1）“了”表发生或完成", "body_zh": "① 语言点解析\n“了”可用于句尾，表示发生或已经完成；也可用于动词后带宾语，该宾语前一般要有定语，如数量词、形容词、代词等。“了”表示发生或已经完成的否定形式为“没……”，同时“了”要去掉。\n［句型框］主语＋动词（宾语）＋了。\n［句型框］主语＋动词＋了＋……宾语。\n［句型框］主语＋没＋动词（宾语）。\n② 语言点导入\n教师可利用本课热身图片F、B、D进行导入。\n教师出示图片F：\n教师：明天她去哪儿？\n学生：明天她去商店。\n教师：昨天她去哪儿了？\n学生：昨天她去商店了。\n图片B：\n教师：她买什么了？\n学生：她买衣服了。\n图片D：\n教师：他买衣服了吗？\n学生：没有，他没买衣服，他买苹果了。\n教师：他买了几个苹果？\n学生：他买了五个苹果。\n③ 语言点操练\n教师可组织学生根据实际情况进行问答练习。\n教师：昨天你看电影了吗？\n学生：昨天我没看电影，我看电视了。\n教师：早上你吃米饭了吗？\n学生：早上我吃米饭了。\n教师：你吃了多少米饭？\n学生：我吃了一点儿米饭。\n④ 语言点扩展练习\n教师可组织学生两人一组，根据提示完成对话练习。\nA：……（时间）你去哪儿了？\nB：……（时间）我去……了。\nA：……（时间）你做什么了？\nB：……（时间）我……了。"}, {"title_zh": "3 语言点（2）名词“后”", "body_zh": "① 语言点解析\n名词“后”表示现在或者所说的某个时间以后的时间。\n［句型框］什么时候／多长时间＋后\n② 语言点导入\n教师：我们什么时候下课？\n学生：我们……分钟后下课。\n教师：你几点吃午饭？\n学生：我……后吃午饭。\n③ 语言点操练\n教师可组织学生根据实际情况进行问答练习。\n目标句：我一个小时后回家。\n我早上九点后去超市。\n我半个小时后去学习汉语。\n④ 语言点扩展练习\n教师可组织学生两人一组根据提示词完成对话练习。\nA：你什么时候……？\nB：……\nA：你什么时候……？\nB：……\n提示词框：去学校　学习汉语　去超市　去买书　回家　去吃中国菜　去看朋友　去买衣服"}, {"title_zh": "3 语言点（3）语气助词“啊”", "body_zh": "语气助词“啊”用在陈述句末，使句子带上一层感情色彩。“啊”与前面的字相邻，在语流中常受到前一字尾音的影响而发生不同的变音，书面上有时按变音写成不同的字。\n① 在a、o、e、i、ü后读ya，汉字可写作“呀”。\n② 在u、ao、ou后读wa，汉字可写作“哇”。\n③ 在-n后读na，汉字可写作“哪”。\n④ 在-ng后读nga，汉字仍写作“啊”。\n⑤ 在zi、ci、si三个音节中的-i[ɿ]后读za，汉字仍写作“啊”。\n⑥ 在zhi、chi、shi三个音节中的-i[ʅ]后读ra，汉字仍写作“啊”。"}, {"title_zh": "3 语言点（4）副词“都”", "body_zh": "① 语言点解析\n副词“都”表示总括全部，所总括的对象必须放在“都”的前面，动词要放在“都”的后边。\n［句型框］主语＋都＋动词。\n② 语言点导入\n教师可利用学生的实际情况进行导入。\n教师：你学习汉语吗？\n学生A：我学习汉语。\n教师：你也学习汉语吗？\n学生B：我也学习汉语。\n教师：你们都学习汉语吗？\n全体学生：对，我们都学习汉语。\n③ 语言点操练\n教师可组织学生根据实际情况进行问答练习。\n目标句：我们都喜欢吃中国菜。\n我们都会说汉语。\n我们都会写汉字。\n我们都不是中国人。\n这些都不是老师的东西。\n……"}, {"title_zh": "4 课文", "body_zh": "课文1\n（1）让学生听两遍录音并回答下列问题：\n昨天上午她去哪儿了？\n她买什么了？\n她买了多少苹果？\n（2）根据学生的回答，教师领说变为叙述体的课文，并请学生单个复述：\n昨天上午她去商店买东西了，她买了一点儿苹果。\n（3）教师领读课文两遍，然后让学生分角色朗读课文。\n课文2\n（1）让学生听两遍录音并回答下列问题：\n他看见张先生了吗？\n张先生去哪儿了？\n张先生什么时候能回来？\n（2）根据学生的回答，教师领说变为叙述体的课文，并请学生单个复述：\n他看见张先生了。张先生去学开车了，40分钟后能回来。\n（3）教师领读课文两遍，然后让学生分角色朗读课文。\n课文3\n（1）让学生听两遍录音并回答下列问题：\n王方的衣服怎么样？\n王方买了多少衣服？\n这些都是谁的东西？\n（2）教师领读课文两遍，然后让学生分角色朗读课文。\n（3）模仿练习\n教师组织学生两人一组，根据提示进行对话练习。\nA：你买什么了？\nB：我买……了。\nA：你买了多少／几＋（量词）……？\nB：我买了……。"}, {"title_zh": "5 语音", "body_zh": "三音节词语的声调搭配（3）：三声音节开头\n教师引导学生将三音节词语的声调模式切分成2+1或者1+2的模式，注意第三声音节的变调。\n教师可利用课本第109页的三音节声调搭配词表进行语音练习。可先领读第一列三音节词语，使学生熟悉练习方法，然后变换齐读、单个学生读、按顺序读、跳读等方法组织学生进行练习。\n练习册相关练习：第105页／三"}, {"title_zh": "6 汉字", "body_zh": "① 知识点解析\n独体字\n开：繁体字的字形像一双手抽拉门栓。本义是抽掉门栓，启动关闭的门。现在意思很多，如驾驶（开车）、开放（开花）。\n车：繁体字的字形像某种器械，两边各有一个轮子，本义是有轮子、靠牛马拉动的战斗工具。现在泛指陆上运输、交通工具，如“出租车”、“火车”。\n回：字形像水流回旋的样子，本义是“旋转”，后来表示“返还、回来”。\n偏旁\n月：肉月旁，一般和人体、肉有关系。\n扌：提手旁，一般表示和手有关的动作。\n② 汉字练习\n• 教师板书或者用手指在空中书写本课独体字“开、车、回”，带领学生一起识记独体字的笔画笔顺。\n• 教师板书本课偏旁“月、扌”，提示学生注意这两个偏旁的笔画和笔顺，并书写各自的代表汉字，帮助学生识记偏旁的意义。\n• 补充练习\n辨认下列汉字并组词\n开（　）／天（　）　回（　）／四（　）\n车（　）／午（　）　服（　）／朋（　）\n练习册相关练习：第106页／四"}, {"title_zh": "7 补充课堂活动——我的周末", "body_zh": "学生3–4人一组，填写下列表格，然后请1–2位学生口头报告小组情况。\n表格：姓名 | 时间 | 事情\n大卫 | 上个星期六晚上 | 跟朋友一起去看电影\n（另有3行空白）\n口头报告：上个星期六晚上，大卫跟朋友一起去看电影了。"}, {"title_zh": "附注：建议教学用具", "body_zh": "1. 生词卡片：第13、14课生词卡片\n2. 独体字卡片：第14课独体字卡片"}], "notes_zh": ["注意：本课含有轻声音节的词语较多，如：东西、先生、回来、衣服、漂亮，教师要注意提示学生轻声音节的声调搭配。（生词）", "注意：“了”字句的否定形式是“没＋动词”，同时“了”要去掉。（语言点1）", "注意：“了”字句带宾语时，宾语前要有数量词、形容词、代词等做定语。（语言点1）"], "warmup_answers_zh": ["答案：①D　②A　③B　④F　⑤E　⑥C"], "text_questions": [{"text": 1, "q_zh": "昨天上午她去哪儿了？"}, {"text": 1, "q_zh": "她买什么了？"}, {"text": 1, "q_zh": "她买了多少苹果？"}, {"text": 2, "q_zh": "他看见张先生了吗？"}, {"text": 2, "q_zh": "张先生去哪儿了？"}, {"text": 2, "q_zh": "张先生什么时候能回来？"}, {"text": 3, "q_zh": "王方的衣服怎么样？"}, {"text": 3, "q_zh": "王方买了多少衣服？"}, {"text": 3, "q_zh": "这些都是谁的东西？"}], "summary_zh": "• 语言点：“……了。”表发生或完成\n　“……后”表示时间\n　语气助词“啊”\n　副词“都”\n• 语音：三音节词语的声调搭配（3）：三声音节开头\n• 汉字：独体字“开、车、回”\n　偏旁“月、扌”"}, "workbook": {"ref": {"book": "workbook", "pages": [107, 108, 109, 110, 111, 112, 113, 114]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听词或短语，判断对错", "instruction_en": "Questions 1-5: Listen to the words or phrases and decide whether the pictures are right or wrong based on what you hear.", "items": [{"n": "例1", "zh": "很高兴 hěn gāoxìng very happy", "transcript_zh": "很高兴", "picture_desc_en": "a smiling young woman with her hair tied back", "answer": "√", "answer_ref": {"book": "workbook", "pages": [107]}}, {"n": "例2", "zh": "看电影 kàn diànyǐng to see a movie", "transcript_zh": "看电影", "picture_desc_en": "an older man in a suit sitting and reading papers", "answer": "×", "answer_ref": {"book": "workbook", "pages": [107]}}, {"n": 1, "zh": "", "transcript_zh": "开车", "picture_desc_en": "two people in helmets riding bicycles through tall grass", "answer": "×", "answer_ref": {"book": "workbook_answers", "pages": [80]}}, {"n": 2, "zh": "", "transcript_zh": "喝茶", "picture_desc_en": "a smiling young woman holding up a glass cup of drink", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [80]}}, {"n": 3, "zh": "", "transcript_zh": "买衣服", "picture_desc_en": "a woman putting clothes into a front-loading washing machine", "answer": "×", "answer_ref": {"book": "workbook_answers", "pages": [80]}}, {"n": 4, "zh": "", "transcript_zh": "书店", "picture_desc_en": "a large room with rows of bookshelves and a few people", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [80]}}, {"n": 5, "zh": "", "transcript_zh": "苹果", "picture_desc_en": "four apples", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [80]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 6-10: Listen to the dialogues and choose the right picture for each dialogue you hear.", "items": [{"n": "例", "zh": "女：你好！ Nǐ hǎo! (How do you do?) 男：你好！很高兴认识你。 Nǐ hǎo! Hěn gāoxìng rènshi nǐ. (How do you do? Nice to meet you.)", "transcript_zh": "女：你好！ 男：你好！很高兴认识你。", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [108]}}, {"n": 6, "zh": "", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "transcript_zh": "男：昨天上午你去哪儿了？ 女：我去学校学汉语了。", "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 7, "zh": "", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "transcript_zh": "男：你去商店买苹果了吗？ 女：没有，我买了不少菜。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 8, "zh": "", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "transcript_zh": "男：你看见张先生了吗？ 女：看见了，他开车去医院了。", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 9, "zh": "", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "transcript_zh": "女：这些是谁的衣服？ 男：丽丽的，她昨天买了不少衣服。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 10, "zh": "", "options": {"A": "[picture] a smiling woman holding a paper grocery bag full of vegetables", "B": "[picture] close-up of a man in a suit with his hands on the steering wheel, driving a car", "C": "[picture] a woman and a man in business clothes shaking hands in front of an elevator", "D": "[picture] a young woman in a knitted hat looking at coats on a clothes rack", "E": "[picture] a smiling woman writing on a whiteboard, a sheet with the character 同 beside her", "F": "[picture] a short-haired young woman talking on a mobile phone, a handbag on her shoulder"}, "transcript_zh": "女：喂，请问，王小姐回来了吗？ 男：没有，她一个小时后回来。", "answer": "F", "answer_ref": {"book": "workbook_answers", "pages": [81]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听句子，回答问题", "instruction_en": "Questions 11-15: Listen to the sentences and answer the questions.", "items": [{"n": "例", "zh": "问：她下午去哪里？", "pinyin": "Tā xiàwǔ qù nǎli?", "transcript_zh": "下午我去商店，我想买一些水果。 问：她下午去哪里？", "options": {"A": "商店 shāngdiàn store", "B": "医院 yīyuàn hospital", "C": "学校 xuéxiào school"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [109]}}, {"n": 11, "zh": "", "transcript_zh": "我上午买了不少菜，中午做饭。 问：他／她上午做什么了？", "options": {"A": "买菜 mǎi cài", "B": "做饭 zuò fàn", "C": "买苹果 mǎi píngguǒ"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 12, "zh": "", "transcript_zh": "这些衣服很漂亮，都是张小姐的。 问：这些衣服都是谁的？", "options": {"A": "小王 xiǎo Wáng", "B": "张小姐 Zhāng xiǎojiě", "C": "王老师 Wáng lǎoshī"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 13, "zh": "", "transcript_zh": "王老师去学校了，她三点后能回来。 问：王老师什么时候能回来？", "options": {"A": "两点后 liǎng diǎn hòu", "B": "三点后 sān diǎn hòu", "C": "四点后 sì diǎn hòu"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 14, "zh": "", "transcript_zh": "下午我和大卫去学开车了。 问：下午大卫做什么了？", "options": {"A": "学习 xuéxí", "B": "学开车 xué kāi chē", "C": "去学校 qù xuéxiào"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [81]}}, {"n": 15, "zh": "", "transcript_zh": "我不爱喝水，不爱吃水果。 问：他／她不爱吃什么？", "options": {"A": "水果 shuǐguǒ", "B": "水 shuǐ", "C": "米饭 mǐfàn"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [81]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第16–20题：看图片，判断图片内容是否与提示词一致", "instruction_en": "Questions 16-20: Look at the pictures and decide whether the given words are right or wrong.", "items": [{"n": "例1", "zh": "电视 diànshì television", "picture_desc_en": "an open laptop computer", "answer": "×", "answer_ref": {"book": "workbook", "pages": [110]}}, {"n": "例2", "zh": "飞机 fēijī airplane", "picture_desc_en": "an airplane in flight", "answer": "√", "answer_ref": {"book": "workbook", "pages": [110]}}, {"n": 16, "zh": "一点儿", "pinyin": "yìdiǎnr", "picture_desc_en": "a large pile of many apples", "answer": "×", "answer_ref": {"book": "workbook_answers", "pages": [82]}}, {"n": 17, "zh": "漂亮", "pinyin": "piàoliang", "picture_desc_en": "a young woman with a headband in a qipao-style top, a paper lantern beside her", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [82]}}, {"n": 18, "zh": "买东西", "pinyin": "mǎi dōngxi", "picture_desc_en": "a smiling woman at a shop counter handing a paper bag to a young man", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [82]}}, {"n": 19, "zh": "不少", "pinyin": "bùshǎo", "picture_desc_en": "an almost empty plate with a knife, a fork and a few leftovers", "answer": "×", "answer_ref": {"book": "workbook_answers", "pages": [82]}}, {"n": 20, "zh": "衣服", "pinyin": "yīfu", "picture_desc_en": "a wicker laundry basket with clothes spilling out", "answer": "√", "answer_ref": {"book": "workbook_answers", "pages": [82]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–25题：看问题，选择正确的回答", "instruction_en": "Questions 21-25: Read the questions and choose the right answer to each of them.", "items": [{"n": "例", "zh": "你喝水吗？ Nǐ hē shuǐ ma? (Would you like some water?)", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "F", "answer_ref": {"book": "workbook", "pages": [111]}}, {"n": 21, "zh": "昨天下午你去商店了吗？", "pinyin": "Zuótiān xiàwǔ nǐ qù shāngdiàn le ma?", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 22, "zh": "我没买水果，你呢？", "pinyin": "Wǒ méi mǎi shuǐguǒ, nǐ ne?", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 23, "zh": "你看见小王了吗？", "pinyin": "Nǐ kànjiàn xiǎo Wáng le ma?", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 24, "zh": "你的衣服太漂亮了！", "pinyin": "Nǐ de yīfu tài piàoliang le!", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 25, "zh": "这些东西是王老师的吗？", "pinyin": "Zhèxiē dōngxi shì Wáng lǎoshī de ma?", "options": {"A": "我去了。 Wǒ qù le.", "B": "我买了一点儿苹果。 Wǒ mǎile yìdiǎnr píngguǒ.", "C": "是，这些都是她的东西。 Shì, zhèxiē dōu shì tā de dōngxi.", "D": "谢谢，我喜欢买漂亮的衣服。 Xièxie, wǒ xǐhuan mǎi piàoliang de yīfu.", "E": "看见了，他开车去学校了。 Kànjiàn le, tā kāi chē qù xuéxiào le.", "F": "好的，谢谢！ Hǎo de, xièxie!"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [83]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第26–30题：看句子，选择正确的词语填空", "instruction_en": "Questions 26-30: Read the sentences and choose the right words to fill in the brackets.", "word_bank": [["A 一点儿 yìdiǎnr", "B 不少 bùshǎo", "C 都 dōu", "D 名字 míngzi", "E 回来 huílái", "F 看见 kànjiàn"]], "items": [{"n": "例", "zh": "你叫什么（________）？", "pinyin": "Nǐ jiào shénme (What is your name?)", "answer": "D", "answer_ref": {"book": "workbook", "pages": [112]}}, {"n": 26, "zh": "你们都来我家吃饭吧，我做了（________）菜。", "pinyin": "Nǐmen dōu lái wǒ jiā chī fàn ba, wǒ zuòle ______ cài.", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 27, "zh": "今天星期五，我想看电影，你什么时候（________）？", "pinyin": "Jīntiān xīngqī wǔ, wǒ xiǎng kàn diànyǐng, nǐ shénme shíhou ______?", "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 28, "zh": "我没（________）王老师的女朋友，很漂亮吧？", "pinyin": "Wǒ méi ______ Wáng lǎoshī de nǚpéngyou, hěn piàoliang ba?", "answer": "F", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 29, "zh": "张小姐住在这儿，小猫和小狗（________）是她的。", "pinyin": "Zhāng xiǎojiě zhù zài zhèr, xiǎo māo hé xiǎo gǒu ______ shì tā de.", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [83]}}, {"n": 30, "zh": "你吃的太少了，多吃（________）吧。", "pinyin": "Nǐ chī de tài shǎo le, duō chī ______ ba.", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [83]}}]}, {"n": "三、语音 第一部分", "type_zh": "语音 第一部分 听力", "instruction_zh": "第1–5题：听录音，从听到的三个词语中选出声调模式不同的一个", "instruction_en": "Questions 1-5: Listen to the recording. Among the three words and phrases you hear, mark the one that has a different tone pattern.", "items": [{"n": 1, "zh": "A　B　C", "options": {"A": "lǎoniánrén（老年人）", "B": "mǎi huángguā（买黄瓜）", "C": "shǐxuéjiā（史学家）"}, "transcript_zh": "A lǎoniánrén（老年人）　B mǎi huángguā（买黄瓜）　C shǐxuéjiā（史学家）", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 2, "zh": "A　B　C", "options": {"A": "biǎoyǎnjiā（表演家）", "B": "lǎonián bìng（老年病）", "C": "xǐ báicài（洗白菜）"}, "transcript_zh": "A biǎoyǎnjiā（表演家）　B lǎonián bìng（老年病）　C xǐ báicài（洗白菜）", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 3, "zh": "A　B　C", "options": {"A": "mǎi qiānbǐ（买铅笔）", "B": "xiǎoshuōjiā（小说家）", "C": "zǒngjīnglǐ（总经理）"}, "transcript_zh": "A mǎi qiānbǐ（买铅笔）　B xiǎoshuōjiā（小说家）　C zǒngjīnglǐ（总经理）", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 4, "zh": "A　B　C", "options": {"A": "dǎ tàijí（打太极）", "B": "hǎo wèntí（好问题）", "C": "lǎonián zǔ（老年组）"}, "transcript_zh": "A dǎ tàijí（打太极）　B hǎo wèntí（好问题）　C lǎonián zǔ（老年组）", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 5, "zh": "A　B　C", "options": {"A": "hǎo péngyou（好朋友）", "B": "zhǎo yínháng（找银行）", "C": "dǎ chángtú（打长途）"}, "transcript_zh": "A hǎo péngyou（好朋友）　B zhǎo yínháng（找银行）　C dǎ chángtú（打长途）", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [84]}}]}, {"n": "三、语音 第二部分", "type_zh": "语音 第二部分 听力", "instruction_zh": "第6–10题：听录音，画出句中你听到的三音节词语", "instruction_en": "Questions 6-10: Listen to the recording and underline the trisyllabic words and phrases in the sentences you hear.", "items": [{"n": 6, "zh": "Mā ma yòng xǐ yī jī xǐ yī fu.", "transcript_zh": "Mā ma yòng xǐ yī jī xǐ yī fu.（妈妈用洗衣机洗衣服。）", "answer": "xǐyījī", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 7, "zh": "Jīn tiān Běi jīng de tiān qì zěn me yàng?", "transcript_zh": "Jīn tiān Běi jīng de tiān qì zěn me yàng?（今天北京的天气怎么样？）", "answer": "zěnmeyàng", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 8, "zh": "Xué xiào li yǒu yì jiā shuǐ guǒ diàn.", "transcript_zh": "Xué xiào li yǒu yì jiā shuǐ guǒ diàn.（学校里有一家水果店。）", "answer": "shuǐguǒdiàn", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 9, "zh": "Xiǎo Zhāng qù shāng diàn mǎi dōng xi le.", "transcript_zh": "Xiǎo Zhāng qù shāng diàn mǎi dōng xi le.（小张去商店买东西了。）", "answer": "mǎidōngxi", "answer_ref": {"book": "workbook_answers", "pages": [84]}}, {"n": 10, "zh": "Tā men qù huǒ chē zhàn mǎi piào le.", "transcript_zh": "Tā men qù huǒ chē zhàn mǎi piào le.（他们去火车站买票了。）", "answer": "huǒchēzhàn", "answer_ref": {"book": "workbook_answers", "pages": [84]}}]}, {"n": "四、汉字 第一部分", "type_zh": "汉字 偏旁归类", "instruction_zh": "第1–2题：看汉字，找出含有下列偏旁的汉字", "instruction_en": "Questions 1-2: Look at the characters and group the characters with the same radical.", "word_bank": [["A 胖", "B 打", "C 肚", "D 接"], ["E 肤", "F 服", "G 抓", "H 抄"]], "items": [{"n": 1, "zh": "月：________", "answer": "A C E F", "answer_ref": {"book": "workbook_answers", "pages": [85]}}, {"n": 2, "zh": "扌：________", "answer": "B D G H", "answer_ref": {"book": "workbook_answers", "pages": [85]}}]}, {"n": "四、汉字 第二部分", "type_zh": "汉字 写独体字", "instruction_zh": "第3题：看笔顺，写独体字", "instruction_en": "Question 3: Look at the stroke order and practice writing the single-component characters.", "items": [{"n": "3-开", "zh": "开 kāi（笔顺4步：一 → 二 → … → 开）"}, {"n": "3-车", "zh": "车 chē（笔顺4步：一 → … → 车）"}, {"n": "3-回", "zh": "回 huí（笔顺6步：丨 → 冂 → … → 回）"}]}], "answers_ref": {"book": "workbook_answers", "pages": [80, 81, 82, 83, 84, 85]}}, "unclear": ["Энэ хичээлд 课堂用语 (classroom_expressions) болон 文化／俗语 хэсэг сурах бичгийн PDF х.124–131-д байхгүй.", "Сурах бичиг PDF х.125 生词 14 «少 shǎo adj. little, few» доор дугааргүй дэд мөр «不少 bùshǎo adj. quite a few, many» хэвлэгдсэн — new_words-д хоёуланг нь n=14-өөр оруулсан (validator-ийн «үгийн дугаар тасархай» анхааруулга үүнээс).", "Гарчгийн пиньинь: сурах бичиг PDF х.124 гарчигт «Tā mǎile bù shǎo yīfu» («bù shǎo» тусдаа), харин 课文3 болон 生词-д «bùshǎo», дасгалын ном PDF х.107 гарчигт «bùshǎo» — title_pinyin-д сурах бичгийн гарчгаар.", "生词 8 «回来 huílai» (сурах бичиг, 2-р үе хөнгөн), харин дасгалын ном PDF х.112 阅读 第三部分 үгийн санд «E 回来 huílái» (2-р хөг) — номд байгаагаар.", "Сурах бичиг PDF х.125 课文3 A-ийн мөр: ханз «王方的衣服太漂亮了！» (анхаарлын тэмдэг), пиньинь «… tài piàoliang le.» (цэг) — номд байгаагаар.", "English Version нь үгчлэн биш: 课文1 «我去商店买东西了» → «I went shopping.»; 课文3 «衣服» → «dress» — номд байгаагаар.", "注释3 啊： сурах бичиг PDF х.127 хүснэгтэд «a e i o ü → ia», харин багшийн ном PDF х.95 «在a、o、e、i、ü后读ya，汉字可写作“呀”» (ia ↔ ya бичлэгийн зөрүү); сурах бичгийн хүснэгтэд zhi/chi/shi/ri, багшийн номд zhi、chi、shi гэж — номд байгаагаар.", "注释1 了： жишээнүүд зөвхөн 3 хүснэгтийн мөр хэлбэрээр хэвлэгдсэн (тусдаа дугаартай өгүүлбэр биш) — structure_rows-д хүснэгтийг, examples-д мөр бүрийг өгүүлбэр болгон нийлүүлж (note_zh = хүснэгтийн дугаар) оруулсан, үг нэмээгүй.", "Сурах бичиг PDF х.129 拼音 хүснэгт 3+4+1 «dǎzìjī tapewriter» — англи орчуулгын хэвлэлийн алдаа (typewriter), номд байгаагаар.", "汉字 хэсэг: 开/车/回-ийн эртний хэлбэрийн хувьсал (字形演变图) болон 田字格 зурлагын дараалал зөвхөн зурагт; дунд алхмууд Unicode-оор бүрэн дүрслэгдэхгүй тул «…» гэж бичсэн. Дасгалын ном PDF х.114 мөн адил.", "Сурах бичиг PDF х.130 偏旁-ийн гарчиг ба хүснэгтэд 肉月旁 тэмдэг (⺼/月 хэлбэр) хэвлэгдсэн; багшийн номд «月» — энд «月» гэж бичсэн.", "Сурах бичиг PDF х.130 汉字 例字 «服 fú» — 衣服 үгэнд хөнгөн (yīfu) боловч хүснэгтэд 2-р хөгөөр — номд байгаагаар.", "Багшийн ном PDF х.95 语言点(3) 啊 — зөвхөн тайлбар ба ①–⑥ дуудлагын дүрэм хэвлэгдсэн, 导入/操练 хэсэг байхгүй.", "Багшийн ном PDF х.94 语言点(1) 导入： «图片D … 他买了五个苹果» — 热身 D зурагт 3 бүтэн алим + хагаслагдсан 1 алим харагдана; номд байгаагаар.", "Багшийн номын хуудасны ишлэлүүд (课本第109页， 练习册第99／102／105／106页) нь хэвлэсэн дугаар (PDF биш).", "Багшийн ном PDF х.96–97 课文 асуултуудад тусдаа хариулт байхгүй; 课文1–2-т нэгдсэн «叙述体» бичвэр л бий (teacher.steps «4 课文») — text_questions-д a_zh оруулаагүй.", "Багшийн ном 汉字 补充练习 «辨认下列汉字并组词» (开/天、回/四、车/午、服/朋) болон сурах бичгийн 练习2 回答问题， 练习3 描述图片 — хариулт хэвлэгдээгүй.", "Дасгалын номын 听力 第三部分 (11–15)-д асуулт хэвлэгдээгүй, зөвхөн сонголтууд — асуултыг transcript_zh-д багшийн номын хавсралтаас (PDF х.130–131).", "Дасгалын номын 听力 болон 语音 бичвэр (transcript_zh, 语音 1–5 сонголтуудын пиньинь/ханз, 6–10 ханз) — багшийн номын хавсралт PDF х.130–131-ээс; дасгалын номд 语音 1–5-д зөвхөн A/B/C үсэг хэвлэгдсэн.", "Дасгалын номын хариулт ХОЁР эх сурвалжид: тусдаа хариултын ном (workbook_answers PDF х.80–85) ба багшийн номын хавсралтын 参考答案 (teacher PDF х.131). Бүгд тохирч байна: 1–5 ×√×√√, 6–10 EABDF, 11–15 ABBBA, 16–20 ×√√×√, 21–25 ABEDC, 26–30 BEFCA, 语音 1–5 AABCA, 6–10 xǐyījī／zěnmeyàng／shuǐguǒdiàn／mǎidōngxi／huǒchēzhàn, 汉字 ACEF／BDGH.", "Дасгалын ном PDF х.114 四、汉字-ийн хоёр дахь хэсэг «第二部分 Part Ⅲ» гэж хэвлэгдсэн (Part Ⅱ биш); 三、语音 болон 四、汉字 хэсгийн дугаарлалт 1-ээс дахин эхэлдэг — номд байгаагаар.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Номын CD тэмдэг: сурах бичиг 课文1–3 = 14-1／14-2／14-3; 拼音 14-4; дасгалын ном 听力 14-1; 语音 14-2.", "Зургийн тайлбарууд (picture_desc_en, pictures_desc_en, options «[picture]») зургаас товч, объектив дүрсэлсэн."], "verified_pages": [80, 81, 82, 83, 84, 85, 92, 93, 94, 95, 96, 97, 98, 107, 108, 109, 110, 111, 112, 113, 114, 124, 125, 126, 127, 128, 129, 130, 131], "schema_version": 1}'::jsonb, 1, 'image_verified')
